                                first = false;
                            }
                            else
                                bounds.Encapsulate(p);
                        }

            result.Log("bodyMin=" + bounds.min.ToString("F5") + " bodyMax=" + bounds.max.ToString("F5") + " scale=" + root.lossyScale.ToString("F5") + " wheelbase=" + v.WheelbaseM + " maxSteer=" + v.MaximumSteeringRad);
